return {
    read(id) { return accepted.get(id) ?? ""; },
    readPersisted(id) { return persisted.get(id) ?? ""; },
    write(id, text, owner) {
      const revision = (revisions.get(id) || 0) + 1;
      revisions.set(id, revision); accepted.set(id, text);
      const event = Object.freeze({ id, text, revision, owner });
      const pending = transport(event);
      return Promise.resolve(pending).then(() => {
        if (revision > (committed.get(id) || 0)) {
          committed.set(id, revision); persisted.set(id, text);
        }
        for (const listener of [...listeners]) listener(event);
        return event;
      });
    },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
  };

return {
    open(id) {
      const ticket = ++request;
      retire();
      if (ticket !== request) return;
      const visit = {id, latest:null};
      visit.task = createTrailingTask((text,owner) => store.write(id,text,owner),120,timers);
      current = visit;
      visit.stop = attachSaveStatus(store,id,owner => current === visit,renderStatus);
      renderDocument({id,text:store.read(id)});
    },
    edit(text) {
      if (!current) return;
      const visit = current, owner = {};
      visit.latest = owner;
      visit.task.push(text,owner);
    },
    close() {
      const ticket = ++request;
      retire();
      if (ticket === request) renderDocument(null);
    },
  };

return store.subscribe(event => {
    if (event.id === id && accepts(event.owner)) renderStatus(event);
  });

browserTimers = {
  schedule(callback, delay) { return setTimeout(callback, delay); },
  cancel(handle) { clearTimeout(handle); },
}

return {
    push(...args) {
      if (handle !== null) timers.cancel(handle);
      pending = args;
      handle = timers.schedule(flush, delay);
    },
    flush,
    cancel() {
      if (handle !== null) timers.cancel(handle);
      handle = null;
      pending = null;
    },
  };

return {
    open(id) { editor.open(id); },
    edit(text) { editor.edit(text); },
    close() { editor.close(); },
    dispose() { editor.close(); },
  };
